    classes: CLASS_CODES,
    pdes: astMeta.pdes,
    name: astMeta.name,
    full_name: astMeta.full_name,
    class: Array.from(astMeta.class),
    pha: Array.from(astMeta.pha),
    H: Array.from(astMeta.H),
    diameter: Array.from(astMeta.diameter),
    moid: Array.from(astMeta.moid),
    spkid: Array.from(astMeta.spkid),
  })
);

console.log("packing comets…");
const comets = JSON.parse(await readFile(join(srcDir, "comets.json"), "utf8"));
const comCount = comets.length;
const comOrbits = new Float32Array(comCount * 10);
const comMeta = {
  count: comCount,
  pdes: new Array(comCount),
  full_name: new Array(comCount),
  class: new Array(comCount),
  M1: new Array(comCount),
  diameter: new Array(comCount),
};

for (let i = 0; i < comCount; i++) {
  const o = comets[i];
  const b = i * 10;
  comOrbits[b] = num(o.a);
  comOrbits[b + 1] = num(o.e, 1);
  comOrbits[b + 2] = num(o.i);
  comOrbits[b + 3] = num(o.om);
  comOrbits[b + 4] = num(o.w);
  comOrbits[b + 5] = num(o.ma);
  comOrbits[b + 6] = num(o.epoch, num(o.tp));
  comOrbits[b + 7] = num(o.n);
  comOrbits[b + 8] = num(o.q);
  comOrbits[b + 9] = num(o.tp);
  comMeta.pdes[i] = o.pdes ?? "";
  comMeta.full_name[i] = (o.full_name ?? o.pdes ?? "").trim();
  comMeta.class[i] = o.class ?? null;
  comMeta.M1[i] = o.M1 ?? null;
  comMeta.diameter[i] = o.diameter ?? null;
}

await writeFile(join(outDir, "comet-orbits.bin"), Buffer.from(comOrbits.buffer));
await writeFile(join(outDir, "comets.json"), JSON.stringify(comMeta));

console.log("packing sentry…");
const sentry = JSON.parse(await readFile(join(srcDir, "sentry.json"), "utf8"));
const sentryByDes = {};
for (const s of sentry) {
  sentryByDes[s.des] = {
    ip: s.ip,
    ps_cum: s.ps_cum,
    ps_max: s.ps_max,
    ts_max: s.ts_max,
    range: s.range,
    n_imp: s.n_imp,
    diameter: s.diameter,
    v_inf: s.v_inf,
    last_obs: s.last_obs,
    fullname: s.fullname,
  };
}
await writeFile(join(outDir, "sentry.json"), JSON.stringify(sentryByDes));

console.log("packing close approaches…");
const cad = JSON.parse(await readFile(join(srcDir, "close-approaches.json"), "utf8"));
const cadByDes = {};
for (const e of cad) {
  const des = e.des;
  let list = cadByDes[des];
  if (!list) {
    list = [];
    cadByDes[des] = list;
  }
  list.push([e.jd, e.dist, e.v_rel, e.cd]);
}
await writeFile(join(outDir, "cad.json"), JSON.stringify(cadByDes));

await copyFile(join(srcDir, "planets.json"), join(outDir, "planets.json"));

const manifest = {
  asteroids: astCount,
  comets: comCount,
  sentry: sentry.length,
  cad: cad.length,
};
await writeFile(join(outDir, "manifest.json"), JSON.stringify(manifest));
console.log("packed", manifest);

args.contents:
:root {
  --bg: #07090e;
  --panel: rgba(10, 14, 22, 0.82);
  --stroke: rgba(180, 210, 255, 0.14);
  --text: #e8eef8;
  --muted: #8b97ab;
  --accent: #7ec8ff;
  --pha: #ff7a3d;
  --sentry: #ff3d7a;
  --comet: #6ef0d4;
  --neo: #9db8d4;
  --gold: #e4c07a;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; height: 100%; background: var(--bg); color: var(--text); overflow: hidden; }
#c { display: block; width: 100%; height: 100%; }
#labels { position: absolute; inset: 0; pointer-events: none; }

.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

.topbar {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; align-items: center; gap: 1.25rem; flex-wrap: wrap;
  padding: 0.7rem 1rem;
  background: linear-gradient(to bottom, rgba(7,9,14,0.92), rgba(7,9,14,0.35) 70%, transparent);
  z-index: 5;
}
.brand { display: flex; gap: 0.7rem; align-items: center; min-width: 12rem; }
.brand .mark {
  width: 0.7rem; height: 0.7rem; border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #fff6c8, #ffb347 40%, #ff6b1a);
  box-shadow: 0 0 12px #ffb347;
}
.brand h1 { margin: 0; font-size: 1.05rem; letter-spacing: 0.04em; font-weight: 650; }
.brand p { margin: 0; font-size: 0.7rem; color: var(--muted); }

.clock { display: flex; align-items: center; gap: 0.6rem; flex: 1; }
.clock input, select, button, input[type="search"] {
  background: rgba(20, 28, 42, 0.9);
  color: var(--text);
  border: 1px solid var(--stroke);
  border-radius: 6px;
  padding: 0.35rem 0.55rem;
  font: inherit;
}
.clock input { font-variant-numeric: tabular-nums; }
.mono { font-variant-numeric: tabular-nums; font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 0.75rem; color: var(--muted); }

.transport { display: flex; align-items: center; gap: 0.4rem; }
button { cursor: pointer; }
button.primary { background: #1c3d66; border-color: #3d6ea8; }
button:hover { border-color: var(--accent); }
.speed { display: flex; align-items: center; gap: 0.35rem; font-size: 0.75rem; color: var(--muted); }

.panel {
  position: absolute; top: 4.4rem; bottom: 3.4rem;
  width: min(22rem, 32vw); overflow: auto;
  background: var(--panel);
  border: 1px solid var(--stroke);
  backdrop-filter: blur(10px);
  padding: 0.85rem 1rem 1.2rem;
  z-index: 4;
}
.panel.left { left: 0.7rem; border-radius: 10px; }
.panel.right { right: 0.7rem; border-radius: 10px; }
.panel h2 { margin: 0 0 0.5rem; font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); }
.panel section { margin-bottom: 1.1rem; }
.panel .empty { color: var(--muted); font-size: 0.85rem; line-height: 1.45; }

.check, .range { display: flex; gap: 0.45rem; align-items: center; font-size: 0.85rem; margin: 0.28rem 0; }
.range { flex-direction: column; align-items: stretch; }
.range span { display: flex; justify-content: space-between; color: var(--muted); font-size: 0.78rem; }
input[type="range"] { width: 100%; accent-color: var(--accent); }
.chips { display: flex; flex-wrap: wrap; gap: 0.3rem; margin: 0.5rem 0; }
.chips button {
  font-size: 0.72rem; padding: 0.2rem 0.45rem; border-radius: 999px;
  opacity: 0.45;
}
.chips button.on { opacity: 1; border-color: var(--accent); color: var(--accent); }

.results { list-style: none; margin: 0.4rem 0 0; padding: 0; max-height: 10rem; overflow: auto; }
.results li { padding: 0.28rem 0.2rem; cursor: pointer; font-size: 0.8rem; border-bottom: 1px solid var(--stroke); }
.results li:hover { color: var(--accent); }

.legend { list-style: none; margin: 0; padding: 0; font-size: 0.8rem; }
.legend li { display: flex; gap: 0.45rem; align-items: center; margin: 0.25rem 0; }
.swatch { width: 0.65rem; height: 0.65rem; border-radius: 50%; display: inline-block; }
.swatch.neo { background: var(--neo); }
.swatch.pha { background: var(--pha); }
.swatch.sentry { background: var(--sentry); }
.swatch.comet { background: var(--comet); }
.hint { font-size: 0.72rem; color: var(--muted); line-height: 1.4; }

.hud { position: absolute; left: 50%; transform: translateX(-50%); bottom: 3.6rem; z-index: 4; text-align: center; pointer-events: none; }
#follow-banner { margin-top: 0.3rem; color: var(--gold); font-size: 0.8rem; pointer-events: auto; }

.timeline {
  position: absolute; left: 24%; right: 24%; bottom: 0.55rem; z-index: 5;
  background: var(--panel); border: 1px solid var(--stroke); border-radius: 10px; padding: 0.35rem 0.8rem 0.45rem;
}
.timeline input { width: 100%; }
.tl-labels { display: flex; justify-content: space-between; font-size: 0.65rem; color: var(--muted); }

.detail-head { display: flex; justify-content: space-between; gap: 0.5rem; align-items: flex-start; }
.detail-head h3 { margin: 0 0 0.15rem; font-size: 1.05rem; }
.badges { display: flex; flex-wrap: wrap; gap: 0.3rem; margin: 0.4rem 0 0.7rem; }
.badge { font-size: 0.68rem; letter-spacing: 0.04em; text-transform: uppercase; border: 1px solid var(--stroke); border-radius: 999px; padding: 0.12rem 0.45rem; color: var(--muted); }
.badge.pha { color: var(--pha); border-color: var(--pha); }
.badge.sentry { color: var(--sentry); border-color: var(--sentry); }
.kv { width: 100%; border-collapse: collapse; font-size: 0.8rem; }
.kv th { text-align: left; color: var(--muted); font-weight: 500; padding: 0.18rem 0.4rem 0.18rem 0; width: 42%; }
.kv td { padding: 0.18rem 0; font-variant-numeric: tabular-nums; }
.actions { display: flex; flex-wrap: wrap; gap: 0.35rem; margin: 0.7rem 0; }
.cad-list { list-style: none; margin: 0; padding: 0; max-height: 14rem; overflow: auto; font-size: 0.78rem; }
.cad-list li { display: grid; grid-template-columns: 1fr auto; gap: 0.2rem; padding: 0.35rem 0; border-bottom: 1px solid var(--stroke); cursor: pointer; }
.cad-list li:hover { color: var(--accent); }
.risk { margin-top: 0.6rem; padding: 0.55rem; border: 1px solid var(--sentry); border-radius: 8px; background: rgba(255, 61, 122, 0.08); }
.risk h4 { margin: 0 0 0.35rem; color: var(--sentry); font-size: 0.75rem; letter-spacing: 0.08em; text-transform: uppercase; }

#loader {
  position: absolute; inset: 0; display: grid; place-items: center;
  background: var(--bg); z-index: 20;
}
#loader.gone { display: none; }
.loader-card { text-align: center; color: var(--muted); }
.spinner {
  width: 2rem; height: 2rem; margin: 0 auto 0.8rem;
  border: 2px solid var(--stroke); border-top-color: var(--accent); border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.label3d {
  color: #dce7f5; font-size: 11px; letter-spacing: 0.04em;
  text-shadow: 0 1px 4px #000;
  white-space: nowrap; user-select: none;
}
.label3d.sun { color: var(--gold); font-weight: 600; }

@media (max-width: 900px) {
  .panel { width: min(18rem, 46vw); top: 6.5rem; }
  .timeline { left: 0.5rem; right: 0.5rem; }
}

const DEG = Math.PI / 180;
const K = 0.01720209895; // Gaussian gravitational constant, au^(3/2) / day

export function wrapPi(a) {
  const t = a % (Math.PI * 2);
  if (t > Math.PI) return t - Math.PI * 2;
  if (t < -Math.PI) return t + Math.PI * 2;
  return t;
}

function keplerE(M, e) {
  M = wrapPi(M);
  let E = e < 0.8 ? M : Math.PI * Math.sign(M || 1);
  for (let n = 0; n < 20; n++) {
    const s = Math.sin(E);
    const c = Math.cos(E);
    const d = (E - e * s - M) / (1 - e * c);
    E -= d;
    if (Math.abs(d) < 1e-10) break;
  }
  return E;
}

function keplerF(M, e) {
  let F = Math.sign(M || 1) * Math.log((2 * Math.abs(M)) / e + 1.8);
  for (let n = 0; n < 25; n++) {
    const sh = Math.sinh(F);
    const ch = Math.cosh(F);
    const d = (e * sh - F - M) / (e * ch - 1);
    F -= d;
    if (Math.abs(d) < 1e-10) break;
  }
  return F;
}

function rotatePerifocal(x, y, i, om, w, out, oi) {
  const cw = Math.cos(w);
  const sw = Math.sin(w);
  const ci = Math.cos(i);
  const si = Math.sin(i);
  const co = Math.cos(om);
  const so = Math.sin(om);
  const px = cw * x - sw * y;
  const py = sw * x + cw * y;
  out[oi] = co * px - so * ci * py;
  out[oi + 1] = so * px + co * ci * py;
  out[oi + 2] = si * py;
}

function meanMotion(a, nDeg) {
  if (nDeg && nDeg > 0) return nDeg * DEG;
  const aa = Math.abs(a);
  if (aa < 1e-8) return 0;
  return K / Math.pow(aa, 1.5);
}

/** Elliptical / circular from mean anomaly at epoch. */
function elliptic(a, e, i, om, w, maDeg, epoch, nDeg, jd, out, oi) {
  const n = meanMotion(a, nDeg);
  const M = maDeg * DEG + n * (jd - epoch);
  const E = keplerE(M, Math.min(e, 0.999999));
  const cE = Math.cos(E);
  const sE = Math.sin(E);
  const r = a * (1 - e * cE);
  const xv = cE - e;
  const yv = Math.sqrt(Math.max(0, 1 - e * e)) * sE;
  const nu = Math.atan2(yv, xv);
  rotatePerifocal(r * Math.cos(nu), r * Math.sin(nu), i, om, w, out, oi);
}

function hyperbolic(q, e, i, om, w, tp, aIn, nDeg, jd, out, oi) {
  const a = aIn > 0 ? aIn : q / Math.max(e - 1, 1e-8);
  const n = meanMotion(a, nDeg);
  const M = n * (jd - tp);
  const F = keplerF(M, e);
  const r = a * (e * Math.cosh(F) - 1);
  const nu = 2 * Math.atan(Math.sqrt((e + 1) / (e - 1)) * Math.tanh(F / 2));
  rotatePerifocal(r * Math.cos(nu), r * Math.sin(nu), i, om, w, out, oi);
}

function parabolic(q, i, om, w, tp, jd, out, oi) {
  const dt = jd - tp;
  const ww = (K / Math.sqrt(2 * q * q * q)) * dt;
  let D = Math.cbrt(ww + Math.sqrt(ww * ww + 1));
  D = D - 1 / D;
  for (let n = 0; n < 8; n++) {
    const f = D * D * D + 3 * D - 3 * ww;
    const df = 3 * D * D + 3;
    D -= f / df;
  }
  const r = q * (1 + D * D);
  const nu = 2 * Math.atan(D);
  rotatePerifocal(r * Math.cos(nu), r * Math.sin(nu), i, om, w, out, oi);
}

/**
 * Asteroid packed layout: a, e, i, om, w, ma, epoch, n  (degrees / au / days)
 * Writes xyz in au into out[oi..oi+2]. Y is ecliptic z so Three.js Y is up.
 */
export function propagateAsteroid(orb, i, jd, out, oi) {
  const b = i * 8;
  const a = orb[b];
  const e = orb[b + 1];
  const inc = orb[b + 2] * DEG;
  const om = orb[b + 3] * DEG;
  const w = orb[b + 4] * DEG;
  elliptic(a, e, inc, om, w, orb[b + 5], orb[b + 6], orb[b + 7], jd, out, oi);
  const z = out[oi + 2];
  out[oi + 2] = -out[oi + 1];
  out[oi + 1] = z;
}

/** Comet packed: a, e, i, om, w, ma, epoch, n, q, tp */
export function propagateComet(orb, i, jd, out, oi) {
  const b = i * 10;
  const a = orb[b];
  const e = orb[b + 1];
  const inc = orb[b + 2] * DEG;
  const om = orb[b + 3] * DEG;
  const w = orb[b + 4] * DEG;
  const q = orb[b + 8];
  const tp = orb[b + 9];
  if (e < 0.995 && a > 0) {
    elliptic(a, e, inc, om, w, orb[b + 5], orb[b + 6], orb[b + 7], jd, out, oi);
  } else if (e < 1.000001) {
    parabolic(q > 0 ? q : Math.abs(a) * (1 - e), inc, om, w, tp, jd, out, oi);
  } else {
    hyperbolic(q, e, inc, om, w, tp, a, orb[b + 7], jd, out, oi);
  }
  const z = out[oi + 2];
  out[oi + 2] = -out[oi + 1];
  out[oi + 1] = z;
}

export function propagateElements(el, jd, out, oi = 0) {
  const a = el.a;
  const e = el.e ?? 0;
  const inc = (el.i ?? 0) * DEG;
  const om = (el.om ?? 0) * DEG;
  const w = (el.w ?? 0) * DEG;
  if (e < 0.995 && a > 0) {
    elliptic(a, e, inc, om, w, el.ma ?? 0, el.epoch, el.n ?? 0, jd, out, oi);
  } else if (e < 1.000001) {
    parabolic(el.q ?? a * (1 - e), inc, om, w, el.tp, jd, out, oi);
  } else {
    hyperbolic(el.q ?? 0, e, inc, om, w, el.tp, a ?? 0, el.n ?? 0, jd, out, oi);
  }
  const z = out[oi + 2];
  out[oi + 2] = -out[oi + 1];
  out[oi + 1] = z;
}

export function sampleOrbit(el, samples = 180) {
  const pts = [];
  const tmp = [0, 0, 0];
  const e = el.e ?? 0;
  if (e < 0.995 && el.a > 0) {
    const period = el.per || (el.n ? 360 / el.n : 365.25 * Math.pow(el.a, 1.5));
    const t0 = el.epoch ?? 2451545;
    for (let i = 0; i <= samples; i++) {
      propagateElements(el, t0 + (period * i) / samples, tmp, 0);
      pts.push(tmp[0], tmp[1], tmp[2]);
    }
  } else {
    const tp = el.tp ?? el.epoch;
    const span = e >= 1 ? 4000 : el.per || 20000;
    for (let i = 0; i <= samples; i++) {
      propagateElements(el, tp + span * (i / samples - 0.5), tmp, 0);
      if (Number.isFinite(tmp[0]) && Math.hypot(tmp[0], tmp[1], tmp[2]) < 200) {
        pts.push(tmp[0], tmp[1], tmp[2]);
      }
    }
  }
  return pts;
}

export function asteroidElements(orb, i) {
  const b = i * 8;
  return {
    a: orb[b],
    e: orb[b + 1],
    i: orb[b + 2],
    om: orb[b + 3],
    w: orb[b + 4],
    ma: orb[b + 5],
    epoch: orb[b + 6],
    n: orb[b + 7],
    per: orb[b + 7] > 0 ? 360 / orb[b + 7] : undefined,
  };
}

export function cometElements(orb, i) {
  const b = i * 10;
  return {
    a: orb[b] || undefined,
    e: orb[b + 1],
    i: orb[b + 2],
    om: orb[b + 3],
    w: orb[b + 4],
    ma: orb[b + 5],
    epoch: orb[b + 6],
    n: orb[b + 7] || undefined,
    q: orb[b + 8],
    tp: orb[b + 9],
    per: orb[b + 7] > 0 ? 360 / orb[b + 7] : undefined,
  };
}

export function dateToJd(date) {
  return date.getTime() / 86400000 + 2440587.5;
}

export function jdToDate(jd) {
  return new Date((jd - 2440587.5) * 86400000);
}

export function formatJd(jd) {
  return `JD ${jd.toFixed(3)}`;
}

export function formatDate(jd) {
  const d = jdToDate(jd);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  return `${y}-${m}-${day} ${hh}:${mm} UTC`;
}

export function toDatetimeLocal(jd) {
  const d = jdToDate(jd);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, "0");
  const day = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  return `${y}-${m}-${day}T${hh}:${mm}`;
}

export function fromDatetimeLocal(value) {
  if (!value) return dateToJd(new Date());
  const [date, time] = value.split("T");
  const [y, mo, d] = date.split("-").map(Number);
  const [hh, mm] = (time || "00:00").split(":").map(Number);
  return dateToJd(new Date(Date.UTC(y, mo - 1, d, hh || 0, mm || 0)));
}

