+}
+
+export function asteroidElements(orb, i) {
+  const b = i * 8;
+  return {
+    a: orb[b],
+    e: orb[b + 1],
+    i: orb[b + 2],
+    om: orb[b + 3],
+    w: orb[b + 4],
+    ma: orb[b + 5],
+    epoch: orb[b + 6],
+    n: orb[b + 7],
+    per: orb[b + 7] > 0 ? 360 / orb[b + 7] : undefined,
+  };
+}
+
+export function cometElements(orb, i) {
+  const b = i * 10;
+  return {
+    a: orb[b] || undefined,
+    e: orb[b + 1],
+    i: orb[b + 2],
+    om: orb[b + 3],
+    w: orb[b + 4],
+    ma: orb[b + 5],
+    epoch: orb[b + 6],
+    n: orb[b + 7] || undefined,
+    q: orb[b + 8],
