+    }
+    if (sel.kind === "planet") {
+      propagateElements(planets[sel.index], jd, out, 0);
+    } else if (sel.kind === "asteroid") {
+      propagateAsteroid(astOrbits, sel.index, jd, out, 0);
+    } else if (sel.kind === "comet") {
+      propagateComet(comOrbits, sel.index, jd, out, 0);
