        <tr><th>a / e / i</th><td>${fmt(el.a, 4)} au · ${fmt(el.e, 4)} · ${fmt(el.i, 2)}°</td></tr>
        <tr><th>Ω / ω / M</th><td>${fmt(el.om, 2)}° · ${fmt(el.w, 2)}° · ${fmt(el.ma, 2)}°</td></tr>
        <tr><th>Period</th><td>${fmt(el.per, 1, "d")}</td></tr>
