    comCol = new Float32Array(comCount * 3);
    comSize = new Float32Array(comCount);
    comVis = new Float32Array(comCount);
    for (let i = 0; i < comCount; i++) {
      comCol[i * 3] = 0.43;
      comCol[i * 3 + 1] = 0.94;
      comCol[i * 3 + 2] = 0.83;
