  }

  function render() {
    controls.update();
    renderer.render(scene, camera);
    labelRenderer.render(scene, camera);
  }

  return {
    resize,
    setPlanets,
    setAsteroids,
    setComets,
    setSentry,
    applyFilter,
    setShow,
    updatePositions,
